		const receipt = input.receipt;
		validateReceiptFields(receipt, identity);
		if (
			!Array.isArray(receipt.steps) ||
			receipt.steps.length !== 3 ||
			new Set(receipt.steps.map((step) => step.id)).size !== 3 ||
			receipt.steps.filter((step) => step.state === 'current').length > 1
		)
			throw Error('Invalid three-step progress');
		for (const step of receipt.steps)
			if (
				!step.id ||
				typeof step.id !== 'string' ||
				typeof step.title !== 'string' ||
				!['done', 'current', 'waiting', 'unknown'].includes(step.state)
